#!/bin/sh
# Fictional quota-observation extension used ONLY by this crate's
# black-box conformance tests (crates/quota-observation/tests/). It is
# not, and must never be mistaken for, a real provider integration — it
# exists purely so the test suite can drive crates/quota-observation's
# one-shot stdio transport against a script whose behaviour the tests
# fully control. See crates/quota-observation/tests/README.md for the
# conformance matrix this exercises.
#
# Absolute paths only: run_one_shot (src/runner.rs) clears PATH before
# exec, so a bare command name would fail to resolve.
#
#   argv[1] = mode (dispatch below)
#   argv[2] = response-template path: a single JSON line, optionally
#             containing the literal placeholder __REQUEST_ID__, which
#             is substituted with the request's own "request_id" value
#             before the line is printed.
#   argv[3] = optional capture path. For every mode except env_probe,
#             the raw request line read from stdin is copied here
#             verbatim (each test uses its own tempdir, so concurrent
#             invocations never share one capture file). For
#             env_probe, the output of /usr/bin/env is written here
#             instead — used only to assert what this process's own
#             environment actually contains, never to exfiltrate
#             anything real.

set -u
mode="$1"
template="$2"
capture="${3:-}"

request="$(/bin/cat)"

if [ "$mode" = "env_probe" ]; then
  if [ -n "$capture" ]; then
    /usr/bin/env >"$capture"
  fi
else
  if [ -n "$capture" ]; then
    printf '%s' "$request" >"$capture"
  fi
fi

# request_id is generated by tests/common/mod.rs using only
# [A-Za-z0-9_.-], so this extraction and the later sed substitution
# never need to handle a sed metacharacter.
req_id=$(printf '%s' "$request" | /usr/bin/sed -n 's/.*"request_id":"\([A-Za-z0-9_.-]*\)".*/\1/p')

# Command substitution strips trailing newlines, so a template file
# that ends in LF (as pre-commit's end-of-file-fixer or an editor
# would leave it) does not leave a second, trailing LF in $frame once
# this script prints its own with `printf '%s\n'` below.
tpl=$(/bin/cat "$template")
frame=$(printf '%s' "$tpl" | /usr/bin/sed "s/__REQUEST_ID__/$req_id/")

case "$mode" in
  ok | env_probe)
    printf '%s\n' "$frame"
    exit 0
    ;;
  nonzero_after_frame)
    printf '%s\n' "$frame"
    exit 7
    ;;
  frame_then_hold)
    # A valid frame is produced, but a backgrounded grandchild keeps
    # stdout open past this leader's own exit — exercises the
    # owned-process-group kill path (runner.rs), not just a direct
    # child kill.
    printf '%s\n' "$frame"
    /bin/sleep 30 &
    exec /bin/sleep 30
    ;;
  stderr_flood)
    i=0
    while [ "$i" -lt 2000 ]; do
      echo "stderr-flood-noise-$i" 1>&2
      i=$((i + 1))
    done
    printf '%s\n' "$frame"
    exit 0
    ;;
  *)
    exit 99
    ;;
esac
